// Creative Engineering. Dust pile blocks (creativeengineering:<metal>_dust_pile) - registered in KubeJS: aluminum/copper/gold/iron/lead/nickel/silver/uranium/zinc/diamond
// and the alloy piles (rose_gold/cast_iron/electrum/steel/constantan), all FallingBlocks
// (Material.METAL, strength 5.0/5.0, gravel sound, requires a tool).
//
// Blockstate, block model and block-item model are generated by KubeJS from the .textureAll() call
// below (cube_all, textures at creativeengineering:block/dust_pile/<metal>_dust_pile.png). KubeJS's
// generated pack outranks mod jars, so hand-authored JSONs in this jar would be ignored; do not add
// them back (they render untextured). Loot table (drop self) is KubeJS's
// block-builder default. Display names ("X Grit Pile") come from
// client_scripts/namechanges.js.
//
// No mineable/tool tag here - CD server creativeengineering/harvest.js owns ALL tool-type (shovel)
// and tool-tier tags for every dust pile in one place, so tags don't fight between two files.

const DUST_PILE_METALS = [
	// Ore metals
	'aluminum', 'copper', 'gold', 'iron', 'lead', 'nickel', 'silver', 'uranium', 'zinc', 'diamond',
	// Alloys
	'rose_gold', 'cast_iron', 'electrum', 'steel', 'constantan', 'brass',
];

var reg = global.reg.forPack('creativeengineering')
StartupEvents.registry('block', e => {
	DUST_PILE_METALS.forEach(metal => {
		reg.block(e, metal + '_dust_pile', 'falling')
			.displayName(metal.split('_').map(w => w.charAt(0).toUpperCase() + w.slice(1)).join(' ') + ' Grit Pile')
			.material('metal')
			.gravelSoundType()
			.hardness(5.0)
			.resistance(5.0)
			.requiresTool(true)
			.textureAll('creativeengineering:block/dust_pile/' + metal + '_dust_pile');
	});
});
